import{_ as a,o as i,c as s,a2 as t}from"./chunks/framework.DXa1R37q.js";const k=JSON.parse('{"title":"Install Neottia in a repository","description":"","frontmatter":{},"headers":[],"relativePath":"get-started/index.md","filePath":"get-started/index.md","lastUpdated":1793132902000}'),n={name:"get-started/index.md"};function o(l,e,h,r,d,p){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="install-neottia-in-a-repository" tabindex="-1">Install Neottia in a repository <a class="header-anchor" href="#install-neottia-in-a-repository" aria-label="Permalink to &quot;Install Neottia in a repository&quot;">​</a></h1><p>This path installs the shared lifecycle and the default Issues and Design Docs capabilities. It does not publish, merge, or change remote services.</p><h2 id="_1-check-the-prerequisites" tabindex="-1">1. Check the prerequisites <a class="header-anchor" href="#_1-check-the-prerequisites" aria-label="Permalink to &quot;1. Check the prerequisites&quot;">​</a></h2><p>You need:</p><ul><li>Node.js 22.20 or newer;</li><li>pnpm 10 or newer;</li><li>a supported AI coding harness: Pi, OpenCode, or Claude Code;</li><li>Git and a local certified filesystem for repository-backed data.</li></ul><p>Read the <a href="/projects/neottia/get-started/requirements">complete runtime and filesystem matrix</a> if you use macOS, Windows, FreeBSD, containers, network storage, or a source build.</p><h2 id="_2-install-the-cli" tabindex="-1">2. Install the CLI <a class="header-anchor" href="#_2-install-the-cli" aria-label="Permalink to &quot;2. Install the CLI&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @neottia/cli</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p>Run the remaining commands from the root of the repository that will own the lifecycle records.</p><h2 id="_3-initialize-one-harness" tabindex="-1">3. Initialize one harness <a class="header-anchor" href="#_3-initialize-one-harness" aria-label="Permalink to &quot;3. Initialize one harness&quot;">​</a></h2><p>Choose one command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pi</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opencode</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude-code</span></span></code></pre></div><p>To support more than one harness in the same repository, repeat the option in one command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude-code</span></span></code></pre></div><p>The command creates <code>.neottia/config.yml</code>. Issues and Design Docs are enabled by default. Add Memory or Searchable only when you intend to use them:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> memory</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> searchable</span></span></code></pre></div><h2 id="_4-compile-and-install" tabindex="-1">4. Compile and install <a class="header-anchor" href="#_4-compile-and-install" aria-label="Permalink to &quot;4. Compile and install&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span></span></code></pre></div><p><code>apply</code> compiles seven commands and the shared operating-protocol skill for every configured harness. It also writes host configuration entries that reference the exact runtime packages required by enabled modules. Each host fetches those packages during its own startup, trust, or launch step.</p><p>Neottia does not overwrite an unowned or modified file. If <code>apply</code> reports a conflict, inspect the named path and follow the <a href="/projects/neottia/operate/troubleshooting#apply-reports-a-conflict">conflict procedure</a>.</p><h2 id="_5-run-diagnostics" tabindex="-1">5. Run diagnostics <a class="header-anchor" href="#_5-run-diagnostics" aria-label="Permalink to &quot;5. Run diagnostics&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>A successful report confirms the configuration, installation receipts, native backend, and required filesystem behavior. Doctor changes nothing and removes its temporary probe area before it returns.</p><h2 id="_6-reload-the-host" tabindex="-1">6. Reload the host <a class="header-anchor" href="#_6-reload-the-host" aria-label="Permalink to &quot;6. Reload the host&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Harness</th><th>Finish setup</th></tr></thead><tbody><tr><td>Pi</td><td>Restart Pi in the project and confirm that <code>/neottia-plan</code> is available.</td></tr><tr><td>OpenCode</td><td>Restart OpenCode in the project and confirm that <code>/neottia-plan</code> is available.</td></tr><tr><td>Claude Code</td><td>Restart Claude Code, confirm <code>/neottia-plan</code>, then approve project servers in <code>/mcp</code>.</td></tr></tbody></table><p>Now complete the <a href="/projects/neottia/get-started/first-success">first successful lifecycle operation</a>.</p><h2 id="what-was-installed" tabindex="-1">What was installed? <a class="header-anchor" href="#what-was-installed" aria-label="Permalink to &quot;What was installed?&quot;">​</a></h2><p>The exact paths differ by harness, but the installation contains:</p><ul><li><code>/neottia-plan</code>, <code>/neottia-build</code>, <code>/neottia-verify</code>, <code>/neottia-release</code>, <code>/neottia-continue</code>, <code>/neottia-refresh</code>, and <code>/neottia-adopt</code>;</li><li>the <code>neottia-sdlc</code> operating-protocol skill;</li><li>runtime package or MCP entries for enabled capabilities;</li><li>a receipt under <code>.neottia/install/</code> that records ownership and checksums.</li></ul><p>See <a href="/projects/neottia/distribution/">distribution and receipts</a> for plan-first installation, updates, uninstall, and recovery.</p>`,30)])])}const u=a(n,[["render",o]]);export{k as __pageData,u as default};
